const ELEMENT_PROP_KEYS = new Set(["theme","title","accentWords","stagger","accent","fontFamily","ink","background","scale","delay","grain","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  title: "Your voice, captioned",
  accentWords: 1,
  stagger: 4,
  accent: "#3B5BFD",
  fontFamily: "Instrument Sans",
  scale: 1,
  delay: 0,
  grain: true,
  speed: 1,
};

type WaveformTitleElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof WaveformTitleBase>;

const WaveformTitleInner = forwardRef<
  HTMLDivElement,
  WaveformTitleElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<WaveformTitle>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <WaveformTitleBase
          {...(componentProps as unknown as ComponentProps<typeof WaveformTitleBase>)}
        />
      </div>
    </Sequence>
  );
});

